    "top_konj_hub_desc": "بیاموزید چگونه کلمات پیونددهنده معنا، روابط منطقی و انسجام ایجاد می‌کنند: چگونه افکار را به هم متصل کنیم، علت و تضاد را بیان کنیم، رویدادها را در زمان قرار دهیم و آنچه را که افراد فکر و احساس می‌کنند گزارش دهیم؟",
