    "top_konj_f8_desc": "درک شناختی متن: به حروف ربط مانند چراغ‌های راهنمایی زبان بنگرید که مسیر را هدایت کرده و جریان طبیعی به متن می‌بخشند.",
    "top_konj_f8_btn": "رفتن به بخش ۸ ➔",
    "top_konj_ped_title": "۳ توصیه آموزشی برای تسلط بر حروف ربط:",
