    "top_konj_ped_item1_desc": "حروف ربط جمله‌های پایه (og, men, eller, for, så) در جایگاه اتصال قرار می‌گیرند و ترتیب واژگان را تغییر نمی‌دهند (ikke بعد از فعل می‌آید). در مقابل، حروف ربط جمله‌های پیرو (fordi, hvis, da, når, at...) کلمه ikke را به قبل از فعل جذب می‌کنند!",
