    "top_konj_f8_desc": "Têgihiştina zanistî ya nivîsê: Gerdêkan wekî îşaretên trafîkê yên ziman bibîne yên ku rê nîşan didin û herikîna nivîsê ya siruştî çêdikin.",
    "top_konj_f8_btn": "Here qada 8 ➔",
    "top_konj_ped_title": "3 şîretên perwerdeyî ji bo fêrbûna gerdêkan:",
    "top_konj_ped_item1_title": "Hevoka sereke vs. hevoka pêvebest (Rêza peyvan)",
    "top_konj_ped_item1_desc": "Gerdêkên hevokên sereke (og, men, eller, for, så) di qada girêdanê de cih digirin û rêza peyvan naguherin (ikke piştî lêkerê dimîne). Lê belê gerdêkên hevokên pêvebest (fordi, hvis, da, når, at...) peyva ikke dikişînin pêşiya lêkerê!",
    "top_konj_ped_item2_title": "Hevoka pêvebest a li pêşiyê dibe sedema pêşketina lêkerê (inversiyon)",
    "top_konj_ped_item2_desc": "Gava ku hevoka pêvebest li destpêkê be, tevahiya cihê 1 digire. Ji ber vê yekê lêkera hevoka sereke divê rasterast li cihê 2 bê (rêza berevajî: lêker berî bîjer).",
