    "top_konj_ped_item3_desc": "\"At\" bilqokeke ramanê ya derûnî vedike da ku nêrîn û hestan vebêje. Gerdêk wekî îşaretên trafîkê dixebitin û di nivîsa te de herikîneke rewan û mentiqî çêdikin.",
