    "top_konj_f3_desc": "在时间线上定位各事件的相对关系：同时发生（mens）、先后顺序（inden、efter at、siden）以及节点与终点（indtil、så snart）。",
    "top_konj_f3_btn": "前往领域 3 ➔",
    "top_konj_f4_badge": "💭 领域 4 • 思维气泡",
    "top_konj_f4_title": "4. 思维气泡与单词 \"at\"",
    "top_konj_f4_desc": "\"at\" 的认知模型：打开一个心理思维气泡，转述人们所想、所信、所感、所承诺、所希望或计划去做的事。",
    "top_konj_f4_btn": "前往领域 4 ➔",
    "top_konj_f5_badge": "⏰ 领域 5 • 时间模型",
    "top_konj_f5_title": "5. \"Da\" 与 \"når\"",
    "top_konj_f5_desc": "认知时间模型：过去单一固定时间点（da）与重复习惯及未来事件（når）之间的区别。",
    "top_konj_f5_btn": "前往领域 5 ➔",
    "top_konj_f6_badge": "🧱 领域 6 • 阻碍与突破",
    "top_konj_f6_title": "6. \"Selvom\" 与 \"alligevel\"",
    "top_konj_f6_desc": "阻碍与突破的认知模型：立起阻碍的高墙（selvom）与势不可挡穿墙而过的重球（alligevel）。",
    "top_konj_f6_btn": "前往领域 6 ➔",
    "top_konj_f7_badge": "⚡ 领域 7 • 因果关系",
    "top_konj_f7_title": "7. \"Fordi\" 与 \"derfor\"",
    "top_konj_f7_desc": "因果关系：驱动力与核心原因（fordi）与后续结果、结论及前进方向（derfor）的认知理解。",
    "top_konj_f7_btn": "前往领域 7 ➔",
    "top_konj_f8_badge": "🚦 领域 8 • 文本交通流",
    "top_konj_f8_title": "8. 文本交通流与句式流畅度",
    "top_konj_f8_desc": "认知文本理解：将连词视为语言的交通信号灯，引导行进方向并创造自然流畅的文本脉络。",
    "top_konj_f8_btn": "前往领域 8 ➔",
    "top_konj_ped_title": "掌握连词的3个教学建议：",
    "top_konj_ped_item1_title": "主句 vs 从句（语序）",
    "top_konj_ped_item1_desc": "并列连词（og、men、eller、for、så）位于连接栏，不改变语序（ikke 位于动词之后）。而从属连词（fordi、hvis、da、når、at...）则会将 ikke 吸引到限定动词之前！",
    "top_konj_ped_item2_title": "从句前置引发倒装",
    "top_konj_ped_item2_desc": "当从句位于句首时，它占据了整个第1位置（前置栏）。因此，主句的限定动词必须紧跟在第2位置（倒装语序：动词在主语之前）。",
    "top_konj_ped_item3_title": "思维气泡与语言交通信号",
    "top_konj_ped_item3_desc": "\"at\" 打开一个心理思维气泡，用以转述观点与感受。连词就像交通信号灯，为你的文本创造流畅且合乎逻辑的行文脉络。",
