    "top_konj_f1_desc": "५ मुख्य संयोजक शब्दहरू (og, men, eller, for, så) मा दक्षता हासिल गर्नुहोस्: जानकारी थप्नुहोस् (og), भिन्नता सिर्जना गर्नुहोस् (men), विकल्पहरू देखाउनुहोस् (eller), कारण दिनुहोस् (for) र परिणाम व्यक्त गर्नुहोस् (så)।",
    "top_konj_f1_btn": "क्षेत्र १ मा जानुहोस् ➔",
    "top_konj_f2_badge": "🎯 क्षेत्र २ • तर्क र भिन्नता",
    "top_konj_f2_title": "२. कारण, सर्त र भिन्नता",
    "top_konj_f2_desc": "गहिरो तार्किक सम्बन्धहरूसँग विचारहरू जोड्नुहोस्: कुनै कुरा किन हुन्छ भनी व्याख्या गर्नुहोस् (fordi), कुन सर्तहरूमा हुन्छ (hvis, om), र कस्ता भिन्नताहरू छन् (selvom)।",
    "top_konj_f2_btn": "क्षेत्र २ मा जानुहोस् ➔",
    "top_konj_f3_badge": "⏳ क्षेत्र ३ • समय र क्रम",
    "top_konj_f3_title": "३. समय र क्रम",
    "top_konj_f3_desc": "समयरेखामा घटनाहरूलाई एकअर्काको तुलनामा राख्नुहोस्: एकै समयमा हुने (mens), अघि र पछि (inden, efter at, siden) तथा समाप्ति (indtil, så snart)।",
    "top_konj_f3_btn": "क्षेत्र ३ मा जानुहोस् ➔",
    "top_konj_f4_badge": "💭 क्षेत्र ४ • विचारको फोका",
    "top_konj_f4_title": "४. विचारको फोका र \"at\" शब्द",
    "top_konj_f4_desc": "\"at\" को लागि संज्ञानात्मक मोडल: दिमागमा विचारको फोका खोल्नुहोस् र मानिसहरू के सोच्छन्, विश्वास गर्छन्, महसुस गर्छन्, वाचा गर्छन्, आशा गर्छन् वा गर्ने योजना बनाउँछन् भनी व्यक्त गर्नुहोस्।",
