    "top_konj_f6_title": "६. \"Selvom\" र \"alligevel\"",
    "top_konj_f6_desc": "अवरोध र सफलताको संज्ञानात्मक मोडल: पर्खाल (selvom) जसले अवरोध खडा गर्छ, र बल (alligevel) जसले त्यसलाई तोडेर अघि बढ्छ।",
